//! The whole generated file: one module per class, and the entry point.

use super::conversions::{ANY_OBJECT, NONE, RC, RUNTIME, SOME};
use super::names::ident;
use super::native;
use super::statements::{Body, BodyKind};
use super::writer::Writer;
use super::{
    CodegenError, CodegenErrorKind, Context, EntryPoint, GeneratedProgram, Result, internal,
};
use crate::Span;
use crate::ast::{ClassDecl, ConstructorDecl, Expr, MemberKind, MethodDecl, VariableKind};
use crate::semantic::{
    BODY_CLASS, CAMERA_3D_CLASS, CAMERA_CLASS, COLOR_CLASS, ClassId, ClassOrigin, GAME_CLASS,
    LIGHT_2D_CLASS, LIGHT_CLASS, MESH_CLASS, MethodInfo, NODE_3D_CLASS, NODE_CLASS, ParameterInfo,
    SOUND_CLASS, SPRITE_CLASS, SceneClassError, Type,
};

/// The engine classes of nodes, which `Scene.load` creates itself.
const NATIVE_NODE_CLASSES: [&str; 8] = [
    NODE_CLASS,
    SPRITE_CLASS,
    CAMERA_CLASS,
    LIGHT_2D_CLASS,
    NODE_3D_CLASS,
    MESH_CLASS,
    LIGHT_CLASS,
    CAMERA_3D_CLASS,
];

/// The engine classes that scripts can extend: the game and the nodes.
const EXTENDABLE_NATIVE_CLASSES: [&str; 9] = [
    GAME_CLASS,
    NODE_CLASS,
    SPRITE_CLASS,
    CAMERA_CLASS,
    LIGHT_2D_CLASS,
    NODE_3D_CLASS,
    MESH_CLASS,
    LIGHT_CLASS,
    CAMERA_3D_CLASS,
];

/// The engine classes that have objects, and so a module and a conversion
/// in `AnyObject`.
const NATIVE_OBJECT_CLASSES: [&str; 12] = [
    GAME_CLASS,
    COLOR_CLASS,
    BODY_CLASS,
    NODE_CLASS,
    SPRITE_CLASS,
    CAMERA_CLASS,
    LIGHT_2D_CLASS,
    NODE_3D_CLASS,
    MESH_CLASS,
    LIGHT_CLASS,
    CAMERA_3D_CLASS,
    SOUND_CLASS,
];

/// Lints that generated code does not follow: it favors simple, uniform
/// translations over idiomatic Rust (`(a).wrapping_add(b)`, unused `mut`,
/// class names as module names, …).
const ALLOWED_LINTS: &str = "dead_code, non_camel_case_types, non_snake_case, unreachable_code, \
    unused_braces, while_true, unused_mut, unused_parens, unused_variables, clippy::all, clippy::pedantic";

/// A class declared in the program, with its declaration.
pub(super) struct ClassItem<'a> {
    pub(super) id: ClassId,
    pub(super) declaration: &'a ClassDecl,
    /// Its own `init`, if it declares one.
    pub(super) constructor: Option<&'a ConstructorDecl>,
}

impl<'a> ClassItem<'a> {
    pub(super) const fn span(&self) -> Span {
        self.declaration.name.span
    }

    /// The initial value of the field whose name is at `span`.
    pub(super) fn field_initializer(&self, span: Span) -> Option<&'a Expr> {
        self.declaration
            .members
            .iter()
            .find_map(|member| match &member.kind {
                MemberKind::Variable(variable) if variable.name.span == span => {
                    variable.initializer.as_ref()
                }
                _ => None,
            })
    }
}

/// Generates the whole file.
pub(super) fn generate(context: Context<'_>) -> Result<GeneratedProgram> {
    let game = context
        .analysis
        .classes()
        .find(GAME_CLASS)
        .ok_or_else(|| internal("engine class `Game` missing", Span::new(0, 0)))?;
    let natives = NATIVE_OBJECT_CLASSES
        .iter()
        .map(|name| {
            context
                .analysis
                .classes()
                .find(name)
                .ok_or_else(|| internal("engine class missing", Span::new(0, 0)))
        })
        .collect::<Result<Vec<_>>>()?;
    let items = class_items(context)?;
    let mut out = Writer::default();
    out.line("// Generated by the StarScript compiler. Do not edit: it is rewritten");
    out.line("// every time the StarScript code is compiled.");
    out.line(&format!("#![allow({ALLOWED_LINTS})]"));
    out.line("");
    let module_classes: Vec<ClassId> = natives
        .iter()
        .copied()
        .chain(items.iter().map(|item| item.id))
        .collect();
    any_object(context, &mut out, &module_classes);
    out.line("");
    out.line("/// One module per class: the engine's, then the program's.");
    out.open("pub mod classes {");
    native::game_module(&mut out);
    out.line("");
    native::node_modules(&mut out);
    for item in &items {
        out.line("");
        context.class_module(&mut out, item)?;
    }
    out.close("}");
    scene_classes(context, &mut out);
    super::scene_fields::scene_fields(context, &mut out);
    let entry_point = entry_point(context, &mut out, &items, game)?;
    Ok(GeneratedProgram {
        code: out.finish(),
        entry_point,
    })
}

/// The program's classes, in source order.
fn class_items(context: Context<'_>) -> Result<Vec<ClassItem<'_>>> {
    let classes = context.analysis.classes();
    let mut items = Vec::new();
    for (id, class) in classes.iter() {
        let ClassOrigin::Script { declaration, .. } = class.origin else {
            continue;
        };
        let declaration = context
            .syntax
            .classes
            .get(declaration)
            .ok_or_else(|| internal("class without declaration", Span::new(0, 0)))?;
        if let Some(base) = class.base {
            let base_info = classes.class(base);
            if base_info.origin == ClassOrigin::Native
                && !EXTENDABLE_NATIVE_CLASSES.contains(&base_info.name.as_str())
            {
                return Err(CodegenError {
                    kind: CodegenErrorKind::NativeBaseClass(classes.class(base).name.clone()),
                    span: declaration.name.span,
                });
            }
        }
        let constructor = declaration
            .members
            .iter()
            .find_map(|member| match &member.kind {
                MemberKind::Constructor(constructor) => Some(constructor),
                _ => None,
            });
        items.push(ClassItem {
            id,
            declaration,
            constructor,
        });
    }
    Ok(items)
}

/// The trait every object implements, to convert it to any of its classes.
fn any_object(context: Context<'_>, out: &mut Writer, classes: &[ClassId]) {
    out.line("/// Implemented by every object: converts it to one of its classes, or");
    out.line("/// gives `None` if it is not an object of that class (`is` and `as`).");
    out.open(&format!(
        "pub trait {} {{",
        ANY_OBJECT.trim_start_matches("crate::")
    ));
    for class in classes {
        out.line(&format!(
            "fn {}(self: {RC}<Self>) -> ::std::option::Option<{}::Ref> {{ {NONE} }}",
            context.member_name(*class),
            context.class_path(*class)
        ));
    }
    out.close("}");
}

/// `new_scene_object_`, which `Scene.load` calls to create a node of the
/// class a scene names: the program's classes that extend `Node` and are
/// created without arguments. The others get the reason they cannot be used.
/// The engine's node classes are created by `Host_::create` itself.
fn scene_classes(context: Context<'_>, out: &mut Writer) {
    let classes = context.analysis.classes();
    out.line("");
    out.line("/// Creates an object of the class a node of a scene names, as its `init()`");
    out.line("/// leaves it.");
    out.open(&format!(
        "pub fn new_scene_object_({UNKNOWN_CLASS_ARGUMENT}: &str) -> ::std::result::Result<crate::classes::Node::Ref, ::std::string::String> {{",
    ));
    out.open(&format!("match {UNKNOWN_CLASS_ARGUMENT} {{"));
    for (id, class) in classes.iter() {
        if NATIVE_NODE_CLASSES.contains(&class.name.as_str()) {
            continue;
        }
        let outcome = match classes.check_scene_class(id) {
            Ok(()) => format!(
                "::std::result::Result::Ok({}::new())",
                context.class_path(id)
            ),
            Err(error) => reason(&error.to_string()),
        };
        out.line(&format!("{:?} => {outcome},", class.name));
    }
    // The message names the class the scene asked for, filled in when it runs.
    let unknown = SceneClassError::Unknown(format!("{{{UNKNOWN_CLASS_ARGUMENT}}}"));
    out.line(&format!(
        "_ => ::std::result::Result::Err(::std::format!({:?})),",
        unknown.to_string()
    ));
    out.close("}");
    out.close("}");
}

/// Parameter of `new_scene_object_`: the class name the scene gives.
const UNKNOWN_CLASS_ARGUMENT: &str = "class_";

/// Code that gives `message` as an error of `new_scene_object_`.
fn reason(message: &str) -> String {
    format!("::std::result::Result::Err(::std::string::String::from({message:?}))")
}

/// Writes `fn main` for the program's entry point, if it has one.
fn entry_point(
    context: Context<'_>,
    out: &mut Writer,
    items: &[ClassItem<'_>],
    game: ClassId,
) -> Result<EntryPoint> {
    let classes = context.analysis.classes();
    let mains = items.iter().filter_map(|item| {
        let main = classes
            .class(item.id)
            .methods
            .iter()
            .find(|m| is_entry_point(m))?;
        Some((
            item,
            EntryPoint::Main,
            main.span.unwrap_or_else(|| item.span()),
        ))
    });
    let games = items
        .iter()
        .filter(|item| is_game(context, items, item.id, game))
        .map(|item| (item, EntryPoint::Game, item.span()));
    let mut entries = mains.chain(games);
    let Some((item, kind, _)) = entries.next() else {
        return Ok(main_scene_entry_point(context, out));
    };
    if let Some((_, _, span)) = entries.next() {
        return Err(CodegenError {
            kind: CodegenErrorKind::SeveralEntryPoints,
            span,
        });
    }
    let path = context.class_path(item.id);
    out.line("");
    if kind == EntryPoint::Main {
        let is_async = classes
            .class(item.id)
            .methods
            .iter()
            .any(|method| is_entry_point(method) && method.is_async());
        out.line("/// Starts the program: runs `static func main()`, and then the");
        out.line("/// coroutines still waiting, until they finish.");
        out.open("pub fn main() {");
        if is_async {
            out.line(&format!(
                "{RUNTIME}::tasks::start({path}::Methods::main());"
            ));
        } else {
            out.line(&format!("{path}::Methods::main();"));
        }
        out.line(&format!("{RUNTIME}::tasks::run_until_finished();"));
        out.close("}");
        return Ok(kind);
    }
    let class = classes.class(item.id);
    if !class.constructor_parameters().is_empty() {
        return Err(CodegenError {
            kind: CodegenErrorKind::GameNeedsArguments(class.name.clone()),
            span: item.span(),
        });
    }
    native::game_entry_point(
        out,
        &format!("{path}::new()"),
        &format!("{:?}", class.name),
        &context.analysis.settings().actions,
    );
    Ok(kind)
}

/// Writes `fn main` for a program without an entry point that plays the
/// project's main scene, if the project has one.
fn main_scene_entry_point(context: Context<'_>, out: &mut Writer) -> EntryPoint {
    let settings = context.analysis.settings();
    let Some(scene) = &settings.main_scene else {
        return EntryPoint::None;
    };
    out.line("");
    native::game_entry_point(
        out,
        &format!("main_scene_game_({:?})?", scene.path),
        &format!("{:?}", scene.title),
        &settings.actions,
    );
    native::main_scene_game(out);
    EntryPoint::MainScene
}

/// Whether `class` is the game: it extends `Game` and no class extends it,
/// so `class MyGame extends BaseGame` runs `MyGame`, not `BaseGame`.
fn is_game(context: Context<'_>, items: &[ClassItem<'_>], class: ClassId, game: ClassId) -> bool {
    let classes = context.analysis.classes();
    classes.is_subclass(class, game)
        && !items
            .iter()
            .any(|other| classes.class(other.id).base == Some(class))
}

/// `static func main()`, with no parameters and no result.
fn is_entry_point(method: &MethodInfo) -> bool {
    method.name == "main"
        && method.is_static
        && method.parameters.is_empty()
        && method.return_type == Type::Void
}

/// `name: Type, …` for a list of parameters.
pub(super) fn parameter_list(
    context: Context<'_>,
    parameters: &[ParameterInfo],
    span: Span,
) -> Result<String> {
    let parameters = parameters
        .iter()
        .map(|parameter| {
            Ok(format!(
                "{}: {}",
                ident(&parameter.name),
                context.rust_type(&parameter.ty, span)?
            ))
        })
        .collect::<Result<Vec<_>>>()?;
    Ok(parameters.join(", "))
}

/// ` -> Type`, or nothing for methods without a result.
fn return_suffix(context: Context<'_>, ty: &Type, span: Span) -> Result<String> {
    if *ty == Type::Void {
        Ok(String::new())
    } else {
        Ok(format!(" -> {}", context.rust_type(ty, span)?))
    }
}

/// ` -> Type` of a method: its result, or for an `async` one the task
/// that gives it.
fn method_return_suffix(context: Context<'_>, method: &MethodInfo, span: Span) -> Result<String> {
    if !method.is_async() {
        return return_suffix(context, &method.return_type, span);
    }
    let result = context.rust_type(&method.return_type, span)?;
    Ok(format!(" -> {RUNTIME}::Task<{result}>"))
}

/// Whether objects of subclasses may run another version of `method`.
const fn is_overridable(method: &MethodInfo) -> bool {
    !method.is_static && !method.is_private
}

impl Context<'_> {
    fn class_module(self, out: &mut Writer, item: &ClassItem<'_>) -> Result<()> {
        let class = self.analysis.classes().class(item.id);
        out.line(&format!("/// `class {}`", class.name));
        out.open(&format!("pub mod {} {{", self.member_name(item.id)));
        out.line("/// A reference to an object of this class or of a subclass.");
        out.line(&format!("pub type Ref = {RC}<dyn Object>;"));
        out.line("");
        self.fields_struct(out, item)?;
        out.line("");
        self.object_trait(out, item)?;
        out.line("");
        self.methods(out, item)?;
        out.line("");
        self.instance(out, item)?;
        out.line("");
        self.constructor(out, item)?;
        out.close("}");
        Ok(())
    }

    fn fields_struct(self, out: &mut Writer, item: &ClassItem<'_>) -> Result<()> {
        let class = self.analysis.classes().class(item.id);
        out.line("/// The fields this class declares.");
        out.open("pub struct Fields {");
        for field in &class.fields {
            out.line(&format!(
                "pub {}: {RUNTIME}::Field<{}>,",
                ident(&field.name),
                self.rust_type(&field.ty, field.span)?
            ));
        }
        out.close("}");
        out.line("");
        out.line("/// Gives access to the fields of this class, in objects of any subclass.");
        out.open("pub trait HasFields {");
        out.line("fn fields(&self) -> &Fields;");
        out.close("}");
        Ok(())
    }

    /// The methods that subclasses may override, as a trait.
    fn object_trait(self, out: &mut Writer, item: &ClassItem<'_>) -> Result<()> {
        let class = self.analysis.classes().class(item.id);
        let base = class.base.map_or_else(
            || ANY_OBJECT.to_owned(),
            |base| format!("{}::Object", self.class_path(base)),
        );
        out.line("/// The methods that objects of a subclass may run their own version of.");
        out.open(&format!("pub trait Object: {base} + HasFields {{"));
        for method in class
            .methods
            .iter()
            .filter(|method| is_overridable(method) && !method.is_override)
        {
            out.line(&format!(
                "{};",
                self.virtual_signature(method, item.span())?
            ));
        }
        out.close("}");
        Ok(())
    }

    /// `fn name(self: Rc<Self>, parameters…) -> Type`
    fn virtual_signature(self, method: &MethodInfo, span: Span) -> Result<String> {
        let parameters = parameter_list(self, &method.parameters, span)?;
        let separator = if parameters.is_empty() { "" } else { ", " };
        Ok(format!(
            "fn {}(self: {RC}<Self>{separator}{parameters}){}",
            ident(&method.name),
            method_return_suffix(self, method, span)?
        ))
    }

    /// Constants and method bodies.
    fn methods(self, out: &mut Writer, item: &ClassItem<'_>) -> Result<()> {
        out.line("/// The constants and the code of the methods of this class.");
        out.line("pub struct Methods;");
        out.line("");
        out.open("impl Methods {");
        let mut first = true;
        for member in &item.declaration.members {
            let written = match &member.kind {
                MemberKind::Variable(variable) if variable.kind == VariableKind::Const => {
                    if !first {
                        out.line("");
                    }
                    let Some(value) = &variable.initializer else {
                        return Err(internal("constant without value", variable.name.span));
                    };
                    self.constant_function(out, item, variable.name.span, value)?;
                    true
                }
                MemberKind::Method(method) => {
                    if !first {
                        out.line("");
                    }
                    self.method_function(out, item, method)?;
                    true
                }
                _ => false,
            };
            first &= !written;
        }
        out.close("}");
        Ok(())
    }

    fn constant_function(
        self,
        out: &mut Writer,
        item: &ClassItem<'_>,
        span: Span,
        value: &Expr,
    ) -> Result<()> {
        let class = self.analysis.classes().class(item.id);
        let constant = class
            .constants
            .iter()
            .find(|constant| constant.span == span)
            .ok_or_else(|| internal("constant without analysis", span))?;
        let body = Body {
            context: self,
            class: item.id,
            kind: BodyKind::Static,
            return_type: constant.ty.clone(),
        };
        out.line(&format!("/// `const {}`", constant.name));
        out.open(&format!(
            "pub fn {}() -> {} {{",
            ident(&constant.name),
            self.rust_type(&constant.ty, span)?
        ));
        out.line(&body.value_as(value, &constant.ty)?);
        out.close("}");
        Ok(())
    }

    fn method_function(
        self,
        out: &mut Writer,
        item: &ClassItem<'_>,
        method: &MethodDecl,
    ) -> Result<()> {
        let span = method.name.span;
        let class = self.analysis.classes().class(item.id);
        let info = class
            .methods
            .iter()
            .find(|info| info.span == Some(span))
            .ok_or_else(|| internal("method without analysis", span))?;
        let parameters = parameter_list(self, &info.parameters, span)?;
        let (receiver, kind) = if info.is_parallel() {
            ("", BodyKind::Parallel)
        } else if info.is_static {
            ("", BodyKind::Static)
        } else if parameters.is_empty() {
            ("this_: &Ref", BodyKind::Method)
        } else {
            ("this_: &Ref, ", BodyKind::Method)
        };
        out.line(&format!("/// `func {}`", info.name));
        out.open(&format!(
            "pub fn {}({receiver}{parameters}){} {{",
            ident(&info.name),
            method_return_suffix(self, info, span)?
        ));
        let body = Body {
            context: self,
            class: item.id,
            kind,
            return_type: info.return_type.clone(),
        };
        if info.is_async() {
            self.coroutine_body(out, item.id, info, &body, method)?;
        } else {
            body.statements(out, &method.body.statements)?;
        }
        out.close("}");
        Ok(())
    }

    /// The body of an `async` method, as a task that owns what it uses:
    /// its object and arguments. A node's coroutines end when it leaves the
    /// game's tree.
    fn coroutine_body(
        self,
        out: &mut Writer,
        class: ClassId,
        info: &MethodInfo,
        body: &Body<'_>,
        method: &MethodDecl,
    ) -> Result<()> {
        let is_node = self
            .analysis
            .classes()
            .find(NODE_CLASS)
            .is_some_and(|node| self.analysis.classes().is_subclass(class, node));
        if info.is_static {
            out.open(&format!("{RUNTIME}::Task::new(async move {{"));
        } else {
            out.line(&format!("let this_ = {RC}::clone(this_);"));
            if is_node {
                out.line(&format!(
                    "let node_ = {RC}::clone(&this_) as crate::classes::Node::Ref;"
                ));
                out.open(&format!("{RUNTIME}::Task::owned(async move {{"));
            } else {
                out.open(&format!("{RUNTIME}::Task::new(async move {{"));
            }
            out.line("let this_ = &this_;");
        }
        body.statements(out, &method.body.statements)?;
        if info.is_static || !is_node {
            out.close("})");
        } else {
            out.close("}, move || crate::classes::Node::in_tree_(&node_))");
        }
        Ok(())
    }

    /// The concrete objects of this class, with the fields of each class of
    /// its hierarchy and the version of each method they run.
    fn instance(self, out: &mut Writer, item: &ClassItem<'_>) -> Result<()> {
        let hierarchy = self.hierarchy(item.id);
        out.line("/// An object created as this class (not as a subclass).");
        out.open("pub struct Instance {");
        for class in &hierarchy {
            out.line(&format!(
                "pub {}: {}::Fields,",
                self.member_name(*class),
                self.class_path(*class)
            ));
        }
        out.close("}");
        for class in &hierarchy {
            let path = self.class_path(*class);
            out.line("");
            out.open(&format!("impl {path}::HasFields for Instance {{"));
            out.line(&format!(
                "fn fields(&self) -> &{path}::Fields {{ &self.{} }}",
                self.member_name(*class)
            ));
            out.close("}");
        }
        out.line("");
        out.open(&format!("impl {ANY_OBJECT} for Instance {{"));
        for class in &hierarchy {
            out.line(&format!(
                "fn {}(self: {RC}<Self>) -> ::std::option::Option<{}::Ref> {{ {SOME}(self) }}",
                self.member_name(*class),
                self.class_path(*class)
            ));
        }
        out.close("}");
        for class in &hierarchy {
            out.line("");
            self.dispatch(out, item, *class)?;
        }
        Ok(())
    }

    /// `impl Ancestor::Object for Instance`: each method runs the version
    /// of the closest class that defines it.
    fn dispatch(self, out: &mut Writer, item: &ClassItem<'_>, ancestor: ClassId) -> Result<()> {
        let classes = self.analysis.classes();
        out.open(&format!(
            "impl {}::Object for Instance {{",
            self.class_path(ancestor)
        ));
        for method in classes
            .class(ancestor)
            .methods
            .iter()
            .filter(|method| is_overridable(method) && !method.is_override)
        {
            let implementer = classes
                .find_member(item.id, &method.name)
                .map_or(ancestor, |found| found.class);
            let path = self.class_path(implementer);
            let arguments: Vec<String> = std::iter::once(format!("&(self as {path}::Ref)"))
                .chain(
                    method
                        .parameters
                        .iter()
                        .map(|parameter| ident(&parameter.name)),
                )
                .collect();
            out.line(&format!(
                "{} {{ {path}::Methods::{}({}) }}",
                self.virtual_signature(method, item.span())?,
                ident(&method.name),
                arguments.join(", ")
            ));
        }
        out.close("}");
        Ok(())
    }
}
